import gzip, os
from collections import defaultdict
import pandas as pd
import numpy as np

# Let's count high-confidence SNPs
# We'll map reads both from 5' end and 3' end

tx_seqs = {}
with gzip.open('/task/input/reference/transcripts.fa.gz', 'rt') as f:
    cur_id, cur_seq = None, []
    for line in f:
        line = line.strip()
        if line.startswith('>'):
            if cur_id:
                tx_seqs[cur_id] = ''.join(cur_seq)
            cur_id = line[1:].split()[0]
            cur_seq = []
        else:
            cur_seq.append(line)
    if cur_id:
        tx_seqs[cur_id] = ''.join(cur_seq)

kmer_pos = {}
for tx, seq in tx_seqs.items():
    for i in range(len(seq) - 24):
        k = seq[i:i+25]
        if k in kmer_pos:
            kmer_pos[k] = None
        else:
            kmer_pos[k] = (tx, i)
unique_kmers = {k: v for k, v in kmer_pos.items() if v is not None}

samples = ['RS21', 'RS38', 'RS46', 'RS50', 'RS53', 'RS60', 'RS65', 'RS66', 'RS76', 'RS84', 'RS91', 'RS92']

# First pass: find candidate loci with robust coverage
locus_counts = defaultdict(lambda: defaultdict(int))

for sid in samples:
    fq = f'/task/input/fastq/{sid}.fastq.gz'
    with gzip.open(fq, 'rt') as f:
        for idx, line in enumerate(f):
            if idx % 4 != 1:
                continue
            read = line.strip()
            k1 = read[:25]
            if k1 in unique_kmers:
                tx, pos = unique_kmers[k1]
                ref_seq = tx_seqs[tx]
                if pos + 50 <= len(ref_seq):
                    ref_sub = ref_seq[pos:pos+50]
                    for offset in range(25, 50):
                        ref_b = ref_sub[offset]
                        read_b = read[offset]
                        loc = f'{tx}:{pos+offset}'
                        locus_counts[loc][read_b] += 1

# Select loci that have at least 100 reads total and at least 20 alternate alleles
good_snps = {}
for loc, counts in locus_counts.items():
    tot = sum(counts.values())
    sorted_bases = sorted(counts.items(), key=lambda x: -x[1])
    if len(sorted_bases) >= 2:
        b1, c1 = sorted_bases[0]
        b2, c2 = sorted_bases[1]
        if c2 >= 30 and c1 >= 30 and tot >= 100:
            good_snps[loc] = (b1, b2)

print(f'Selected {len(good_snps)} robust biallelic SNPs.')

# Second pass: compute allele frequency of b2 in each sample
freqs = {loc: {} for loc in good_snps}
for sid in samples:
    sid_counts = defaultdict(lambda: defaultdict(int))
    fq = f'/task/input/fastq/{sid}.fastq.gz'
    with gzip.open(fq, 'rt') as f:
        for idx, line in enumerate(f):
            if idx % 4 != 1:
                continue
            read = line.strip()
            k1 = read[:25]
            if k1 in unique_kmers:
                tx, pos = unique_kmers[k1]
                ref_seq = tx_seqs[tx]
                if pos + 50 <= len(ref_seq):
                    for offset in range(25, 50):
                        loc = f'{tx}:{pos+offset}'
                        if loc in good_snps:
                            sid_counts[loc][read[offset]] += 1
    for loc in good_snps:
        b1, b2 = good_snps[loc]
        c1 = sid_counts[loc][b1]
        c2 = sid_counts[loc][b2]
        tot = c1 + c2
        freqs[loc][sid] = (c2 / tot) if tot >= 5 else np.nan

df_freq = pd.DataFrame(freqs).T
print('SNP allele frequencies shape:', df_freq.shape)
print('\nSample correlation of allele frequencies:')
print(df_freq.corr().round(3))
